-- plan sha256 efe6eb0653ea2caa476a111cfe92af71dc6e771a0f84d9072c4ec1ca932b6b26
-- Generated by scripts/remediation/mechanical/apply.py - do not edit by hand.
-- 6 row(s) over 6 site(s); scope source_id = 'ancient_nerds';
-- run stamp 'wb-teaser-card-s035'; journal test id 'WB/teaser-card'.
-- Every UPDATE is conditioned on the old value the plan names; every change is journalled
-- in the same transaction, so the audit trail cannot disagree with the data.
\set ON_ERROR_STOP on
BEGIN;

-- The server bounds this transaction itself: a lock wait or a runaway statement raises
-- here, psql stops the script (exit 3) and nothing is kept. A client that gives up does
-- not stop the server - psql has the whole script on its stdin.
SET LOCAL lock_timeout = '10s';
SET LOCAL statement_timeout = '120s';

CREATE TEMP TABLE _teaser_card_plan (
    site_id     UUID NOT NULL,
    column_name TEXT NOT NULL,
    old_value   TEXT,
    new_value   TEXT,
    change_key  TEXT NOT NULL,
    reason      TEXT NOT NULL,
    premise     TEXT NOT NULL,
    evidence    JSONB NOT NULL,
    PRIMARY KEY (site_id, column_name)
) ON COMMIT DROP;

INSERT INTO _teaser_card_plan (site_id, column_name, old_value, new_value, change_key, reason, premise, evidence) VALUES
    ('5d975f0c-bbe4-4bd4-9436-5bf4f2bd59b6'::uuid, 'card_description', 'At the end of the Avenue of the Dead rises the Pyramid of the Moon, a stage for ritual sacrifice and a burial ground for its victims: felines, birds of prey, snakes and humans.', NULL, 'teaser-card-s035:5d975f0c-bbe4-4bd4-9436-5bf4f2bd59b6:card_description', 'teaser-card-s035 (card-clear-owner-d47-contradicted): card cleared (owner-d47-contradicted)', '||49cbfd8d6d282fd4e9115eef74747bc1acaf9ddd61faef5914744a34ad7c9629', '[{"source": "lane WB run owner-d47-2026-10-19: owner-d47-contradicted", "url": "output/remediation/teaser/runs/owner-d47-2026-10-19/OUTCOMES.jsonl", "quote": "owner decision D47 (2026-10-19): adjudicated contradicted in output/remediation/calibration/teaser-gold/ADJUDICATION.json - orchestrator (Claude Opus 5.5), 2026-10-09, from the adversarial dispute list: the source list ends ''and more'' and Burial 6 also held canids: the card drops the qualifier and presents the list as complete"}]'::jsonb),
    ('6799d014-2963-4be7-954d-6a50ebbdcbc4'::uuid, 'card_description', 'The steep banks and ditches of Caesar''s Camp, an Iron Age hill fort south of Bracknell, trace an oak leaf. At its tip, multiple banks and a sinuous road guard the main entrance.', NULL, 'teaser-card-s035:6799d014-2963-4be7-954d-6a50ebbdcbc4:card_description', 'teaser-card-s035 (card-clear-owner-d47-contradicted): card cleared (owner-d47-contradicted)', '||3377a6d6320b80575a3969673c34e69dfdc04605b57b959fa4e6861780664bbf', '[{"source": "lane WB run owner-d47-2026-10-19: owner-d47-contradicted", "url": "output/remediation/teaser/runs/owner-d47-2026-10-19/OUTCOMES.jsonl", "quote": "owner decision D47 (2026-10-19): adjudicated contradicted in output/remediation/calibration/teaser-gold/ADJUDICATION.json - orchestrator (Claude Opus 5.5), 2026-10-09, from the adversarial dispute list: Historic England 1016334: a single massive rampart bank, and the north entrance probably not original"}]'::jsonb),
    ('6a8bc59c-77c3-4359-8f65-19f67ee0ac04'::uuid, 'card_description', 'Near modern Bali, on the north coast of Crete, lay Astale, a Roman town and the harbour of Axus. The Stadiasmus Maris Magni placed it 300 stadia from Herakleion.', NULL, 'teaser-card-s035:6a8bc59c-77c3-4359-8f65-19f67ee0ac04:card_description', 'teaser-card-s035 (card-clear-owner-d47-contradicted): card cleared (owner-d47-contradicted)', '||25bf60d48ad66fe9389f99f4ec9aa918bf41c2602405ed7ddeb9f67e5c191ac7', '[{"source": "lane WB run owner-d47-2026-10-19: owner-d47-contradicted", "url": "output/remediation/teaser/runs/owner-d47-2026-10-19/OUTCOMES.jsonl", "quote": "owner decision D47 (2026-10-19): adjudicated contradicted in output/remediation/calibration/teaser-gold/ADJUDICATION.json - orchestrator (Claude Opus 5.5), 2026-10-09, from the web_verifier dispute list: the Stadiasmus (topostext work 217) gives 100 stades from Astale to Herakleion, not 300"}]'::jsonb),
    ('9c776b7e-cc75-46e4-a169-2aa16b47ae86'::uuid, 'card_description', 'In the southern Alentejo lie the Roman Ruins of São Cucufate, the remains of a Roman-era farm in Vila de Frades. Jorge Alarcão and R. Etienne began the first excavations in 1979.', NULL, 'teaser-card-s035:9c776b7e-cc75-46e4-a169-2aa16b47ae86:card_description', 'teaser-card-s035 (card-clear-owner-d47-contradicted): card cleared (owner-d47-contradicted)', '||ecb5c307be25539dbd2fcc59ea6111511ae89a2e4150b073bdddf6a6e519d839', '[{"source": "lane WB run owner-d47-2026-10-19: owner-d47-contradicted", "url": "output/remediation/teaser/runs/owner-d47-2026-10-19/OUTCOMES.jsonl", "quote": "owner decision D47 (2026-10-19): adjudicated contradicted in output/remediation/calibration/teaser-gold/ADJUDICATION.json - orchestrator (Claude Opus 5.5), 2026-10-09, from the web_verifier dispute list: first excavated by D. Fernando de Almeida in 1970 (Portuguese heritage register), not 1979"}]'::jsonb),
    ('a2c6e1bf-1538-43c4-ad4a-65a0186193a7'::uuid, 'card_description', 'Found in 2008, the North Bersted Man was a warrior buried in the first century BC with an exceptional set of objects, his helmet adorned with two crests that once ran down its back.', NULL, 'teaser-card-s035:a2c6e1bf-1538-43c4-ad4a-65a0186193a7:card_description', 'teaser-card-s035 (card-clear-owner-d47-contradicted): card cleared (owner-d47-contradicted)', '||16d5bd81ed1bb7966f42c76cd407ae33685c34cffd6948fa1bbdf6e83aa6130f', '[{"source": "lane WB run owner-d47-2026-10-19: owner-d47-contradicted", "url": "output/remediation/teaser/runs/owner-d47-2026-10-19/OUTCOMES.jsonl", "quote": "owner decision D47 (2026-10-19): adjudicated contradicted in output/remediation/calibration/teaser-gold/ADJUDICATION.json - orchestrator (Claude Opus 5.5), 2026-10-09, from the web_verifier dispute list: one crest ran ear to ear and only one down the back (Current Archaeology)"}]'::jsonb),
    ('e62c980a-351d-40c1-8297-05f52f72a59c'::uuid, 'card_description', 'Over the Cakircak stream in ancient Caria, the Nysa Bridge runs some 100 m like a tunnel, though built entirely above ground: a Roman vault carrying the area before the city theatre.', NULL, 'teaser-card-s035:e62c980a-351d-40c1-8297-05f52f72a59c:card_description', 'teaser-card-s035 (card-clear-owner-d47-contradicted): card cleared (owner-d47-contradicted)', '||ac7f113ae8d5deb2197233b8a88d3d909b8cd181c6861e7268d59c2ff1b18605', '[{"source": "lane WB run owner-d47-2026-10-19: owner-d47-contradicted", "url": "output/remediation/teaser/runs/owner-d47-2026-10-19/OUTCOMES.jsonl", "quote": "owner decision D47 (2026-10-19): adjudicated contradicted in output/remediation/calibration/teaser-gold/ADJUDICATION.json - orchestrator (Claude Opus 5.5), 2026-10-09, from the adversarial dispute list: the bridge is collapsed between m 75 and 85; the present-tense ''runs some 100 m'' is false"}]'::jsonb);

DO $$
DECLARE
    bad      INTEGER;
    moved    INTEGER := 0;
    expected INTEGER := 6;
    r        RECORD;
BEGIN
    -- expected is the plan's own row count, rendered here, and not a second count of the
    -- temp table the loop below iterates: counting the same table twice would make the
    -- comparison after the loop a tautology. The instance that makes a short loop
    -- unreachable is apply_remediation_change, which raises unless exactly one row
    -- matched; this guard is what reports a loop that changed fewer rows than the plan.

    -- scope guard 1: every planned row is a card_stats row of a curated site that still exists
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p LEFT JOIN card_stats t ON t.site_id = p.site_id
      LEFT JOIN unified_sites u ON u.id = p.site_id
     WHERE t.site_id IS NULL OR u.id IS NULL OR u.source_id <> 'ancient_nerds';
    IF bad > 0 THEN
        -- the source name is a RAISE argument, never part of the quoted message: a name
        -- spliced into the message text only parses while the name happens to contain no
        -- quote, which is a property of today's value and not of this code. G0's guard is
        -- the shape this one copies.
        RAISE EXCEPTION 'teaser card: % planned row(s) are not % sites', bad, 'ancient_nerds';
    END IF;

    -- scope guard 2: the plan is a set of real changes, each one writable in its column
    -- (compared in the column's own type; CASE, because only CASE fixes the order in
    -- which the casts are evaluated)
    SELECT count(*) INTO bad FROM _teaser_card_plan p
     WHERE p.new_value = '' OR CASE p.column_name
                WHEN 'card_description' THEN p.new_value::character varying IS NOT DISTINCT FROM p.old_value::character varying OR length(p.new_value) > 200
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) are not writable changes', bad;
    END IF;

    -- scope guard 3: every planned row still holds the old value the plan names
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p JOIN card_stats t ON t.site_id = p.site_id
     WHERE CASE p.column_name
                WHEN 'card_description' THEN t.card_description IS DISTINCT FROM p.old_value::character varying
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) no longer hold the planned old value', bad;
    END IF;

    -- scope guard 5: every planned row still holds the input its value was derived from
    SELECT count(*) INTO bad
      FROM (SELECT DISTINCT site_id, premise FROM _teaser_card_plan) p JOIN unified_sites u ON u.id = p.site_id
     WHERE (coalesce(u.raw_data -> '_card_provenance' ->> 'text_sha256', '') || '|' || coalesce(u.raw_data -> '_card_provenance' ->> 'desc_sha256', '') || '|' || encode(sha256(convert_to(coalesce(u.description, ''), 'UTF8')), 'hex')) IS DISTINCT FROM p.premise;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) no longer hold the premise the plan derived its value from', bad;
    END IF;

    -- the only writer: the conditional UPDATE and its journal row commit together, and
    -- the function raises unless exactly one row matched
    FOR r IN SELECT * FROM _teaser_card_plan ORDER BY site_id, column_name LOOP
        moved := moved + apply_remediation_change(
            'card_stats', r.column_name, 'site_id', r.site_id::text,
            r.old_value, r.new_value,
            'WB/teaser-card', 'wb-teaser-card-s035', r.change_key, 'opus-checked', r.evidence, r.site_id);
    END LOOP;

    IF moved <> expected THEN
        RAISE EXCEPTION 'teaser card: % row(s) changed, % planned', moved, expected;
    END IF;

    -- invariant 1: every planned row now holds the new value
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p JOIN card_stats t ON t.site_id = p.site_id
     WHERE CASE p.column_name
                WHEN 'card_description' THEN t.card_description IS DISTINCT FROM p.new_value::character varying
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) do not hold the new value', bad;
    END IF;

    -- invariant 2: the journal and the data agree, row for row, in both directions
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p LEFT JOIN remediation_change_log l
        ON l.row_pk = p.site_id::text AND l.table_name = 'card_stats'
       AND l.column_name = p.column_name
       AND l.run_stamp = 'wb-teaser-card-s035'
     WHERE l.id IS NULL
        OR l.new_value IS DISTINCT FROM p.new_value
        OR l.old_value IS DISTINCT FROM p.old_value;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) have no matching journal row', bad;
    END IF;

    SELECT count(*) INTO bad FROM remediation_change_log l
     WHERE l.run_stamp = 'wb-teaser-card-s035'
       AND (l.table_name <> 'card_stats' OR l.column_name NOT IN ('card_description'));
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: this run stamp journalled % row(s) outside card_stats.(card_description)', bad;
    END IF;

    RAISE NOTICE 'teaser card: % of % planned cell(s) changed and journalled over 6 curated site(s)',
        moved, expected;
END $$;

COMMIT;

-- Post-commit read: the numbers the report quotes, from the database, not from the plan.
SELECT 'journal rows for this run stamp' AS metric, count(*)::text AS value
  FROM remediation_change_log WHERE run_stamp = 'wb-teaser-card-s035'
UNION ALL
SELECT 'journal rows for this test id', count(*)::text
  FROM remediation_change_log WHERE test_id = 'WB/teaser-card'
UNION ALL
SELECT 'planned rows now holding the new value', count(*)::text
  FROM remediation_change_log l
 WHERE l.run_stamp = 'wb-teaser-card-s035' AND l.table_name = 'card_stats'
   AND l.column_name IN ('card_description')
   AND EXISTS (SELECT 1 FROM card_stats t
                WHERE t.site_id::text = l.row_pk AND CASE l.column_name
                WHEN 'card_description' THEN t.card_description IS NOT DISTINCT FROM l.new_value::character varying
                ELSE false END)
UNION ALL
SELECT 'curated sites whose teaser provenance does not hash their live card', count(*)::text
  FROM unified_sites
 WHERE source_id = 'ancient_nerds' AND raw_data ? '_card_provenance' AND NOT EXISTS (SELECT 1 FROM card_stats cs WHERE cs.site_id = unified_sites.id AND encode(sha256(convert_to(cs.card_description, 'UTF8')), 'hex') = unified_sites.raw_data -> '_card_provenance' ->> 'text_sha256')
UNION ALL
SELECT 'curated sites', count(*)::text
  FROM unified_sites WHERE source_id = 'ancient_nerds';
